
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_fd_lb94_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_fd_lb94", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.644230474285059e+00, -5.583592098828570e+00, -5.499825997981691e+00, -5.386319011709112e+00, -5.236991150977540e+00, -5.049534178753054e+00, -4.831961982637886e+00, -4.612993509763665e+00, -4.445854533427851e+00, -4.308709320699067e+00, -3.384309913910934e+00, -1.089115545552271e+00, -7.254201317305521e-01, -7.784297125903168e-01, -8.279004179379807e-01, -9.293782055895806e-01, -1.186445970787855e+00, -1.712263034615817e+00, -2.691488633727015e+00, -4.426435859623160e+00]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


